import * as React from "react"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};


// Vinyl Project Roll v5 — user-configured release defaults / cylindrical vertical roll / record reveal
// No external libraries or hosted images are needed for the sample content.

type ImageValue = string | { src?: string; srcSet?: string; alt?: string }
type Project = {
    title: string
    image?: ImageValue
    discLabel?: string
    description?: string
    link?: string
    labelColor?: string
}

type Layout = {
    coverSize: number
    rowSpacing: number
    visibleNeighbors: number
    idleTilt: number
    perspective: number
    verticalOffset: number
    coverRadius: string
    background: string
}
type Sleeve = {
    edgeHeight: number
    paperColor: string
    edgeColor: string
    textColor: string
    border: any
    shadow: any
    gloss: number
    grain: number
    titleFont: any
}
type Vinyl = {
    recordColor: string
    labelColor: string
    labelTextColor: string
    labelScale: number
    reveal: number
    grooves: number
    shine: number
    animationSeconds: number
    spinOnOpen: boolean
}
type Interaction = {
    wheelEnabled: boolean
    wheelPixels: number
    dragEnabled: boolean
    dragPixels: number
    showDescription: boolean
    pauseOnHover: boolean
    showCloseButton: boolean
    newTab: boolean
}
type Props = {
    projects: Project[]
    autoRotate: boolean
    secondsPerItem: number
    direction: "forward" | "reverse"
    layout: Layout
    sleeve: Sleeve
    vinyl: Vinyl
    interaction: Interaction
}

