function getSrc(image?: ImageValue): string {
    if (!image) return ""
    if (typeof image === "string") return image
    return image.src || ""
}

function clamp(value: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, value))
}

function wrappedDelta(index: number, current: number, total: number): number {
    if (total < 2) return 0
    return ((index - current + total * 500 + total / 2) % total) - total / 2
}

function nearestPositionTo(
    index: number,
    current: number,
    total: number
): number {
    return current + wrappedDelta(index, current, total)
}

function useSize(ref: React.RefObject<HTMLDivElement>) {
    const [size, setSize] = React.useState({ width: 1180, height: 780 })
    React.useEffect(() => {
        const el = ref.current
        if (!el) return
        const measure = () => {
            const rect = el.getBoundingClientRect()
            setSize({ width: rect.width || 1180, height: rect.height || 780 })
        }
        measure()
        if (typeof ResizeObserver === "undefined") return
        const observer = new ResizeObserver(measure)
        observer.observe(el)
        return () => observer.disconnect()
    }, [ref])
    return size
}

// Small deterministic grain texture. No raster grain asset or network request.
const GRAIN_SVG = `url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.64' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.30'/%3E%3C/svg%3E")`

type CoverProps = {
    project: Project
    size: number
    layout: Layout
    sleeve: Sleeve
    straight?: boolean
}
function SleeveCover({ project, size, layout, sleeve }: CoverProps) {
    const src = getSrc(project.image)
    const [error, setError] = React.useState(false)
    React.useEffect(() => setError(false), [src])
    const edgeHeight = clamp(sleeve.edgeHeight * (size / 545), 11, 60)
    const border = sleeve.border || DEFAULT_SLEEVE.border
    const textStyle = { ...DEFAULT_SLEEVE.titleFont, ...sleeve.titleFont }
    const requestedSize = textStyle.fontSize || "15px"
    const scaledFontSize =
        typeof requestedSize === "number"
            ? `${clamp((requestedSize * size) / 545, 9, 75)}px`
            : typeof requestedSize === "string" &&
                /^\d+(\.\d+)?px$/.test(requestedSize)
              ? `${clamp((parseFloat(requestedSize) * size) / 545, 9, 75)}px`
              : requestedSize
    return (
        <div
            style={{
                width: "100%",
                height: "100%",
                position: "relative",
                borderRadius: layout.coverRadius,
                background: sleeve.paperColor,
                isolation: "isolate",
                overflow: "hidden",
                borderColor: border.borderColor || "rgba(0,0,0,.12)",
                borderStyle: border.borderStyle || "solid",
                borderWidth: border.borderWidth ?? 1,
                boxShadow: sleeve.shadow,
                boxSizing: "border-box",
                backfaceVisibility: "hidden",
            }}
        >
            <div
                style={{
                    position: "absolute",
                    inset: 0,
                    background:
                        "linear-gradient(130deg,#D9D4C9 0%,#B6C3BE 36%,#AC9F90 100%)",
                }}
            />
            {src && !error ? (
                <img
                    src={src}
                    alt={project.title || "Project cover"}
                    srcSet={
                        typeof project.image === "object"
                            ? project.image?.srcSet
                            : undefined
                    }
                    draggable={false}
                    onError={() => setError(true)}
                    style={{
                        position: "absolute",
                        inset: 0,
                        width: "100%",
                        height: "100%",
                        objectFit: "cover",
                        display: "block",
                    }}
                />
            ) : (
                <div
                    style={{
                        position: "absolute",
                        inset: "8%",
                        border: "1px solid rgba(255,255,255,.3)",
                        background:
                            "radial-gradient(ellipse at 35% 25%,rgba(255,255,255,.50),transparent 36%),linear-gradient(135deg,#D8BEB0,#748C90)",
                    }}
                />
            )}
            {/* Gloss lacquer and laminate reflections */}
            <div
                style={{
                    position: "absolute",
                    inset: 0,
                    pointerEvents: "none",
                    background:
                        "linear-gradient(132deg,rgba(255,255,255,.46) 0%,transparent 20%,transparent 58%,rgba(0,0,0,.22) 100%),linear-gradient(100deg,transparent 23%,rgba(255,255,255,.30) 35%,transparent 45%)",
                    opacity: clamp(sleeve.gloss, 0, 1),
                    mixBlendMode: "screen",
                }}
            />
            {sleeve.grain > 0 && (
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        backgroundImage: GRAIN_SVG,
                        backgroundSize: "160px 160px",
                        opacity: sleeve.grain * 0.35,
                        mixBlendMode: "multiply",
                        pointerEvents: "none",
                    }}
                />
            )}
            {/* Subtle binding fold and front-edge spine. Text is the project title only. */}
            <div
                style={{
                    position: "absolute",
                    inset: 0,
                    pointerEvents: "none",
                    boxShadow:
                        "inset 0 2px 2px rgba(255,255,255,.40),inset 3px 0 3px rgba(0,0,0,.11),inset -2px 0 2px rgba(0,0,0,.07)",
                }}
            />
            <div
                style={{
                    position: "absolute",
                    bottom: 0,
                    left: 0,
                    right: 0,
                    height: edgeHeight,
                    background: project.labelColor || sleeve.edgeColor,
                    borderTop: "1px solid rgba(0,0,0,.17)",
                    boxShadow:
                        "0 -2px 3px rgba(0,0,0,.09),inset 0 2px 1px rgba(255,255,255,.65)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    padding: "0 3%",
                    boxSizing: "border-box",
                }}
            >
                <span
                    style={{
                        ...textStyle,
                        color: sleeve.textColor,
                        fontSize: scaledFontSize,
                        lineHeight: 1.1,
                        whiteSpace: "nowrap",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        maxWidth: "100%",
                    }}
                >
                    {project.title || "Untitled"}
                </span>
            </div>
        </div>
    )
}

// Image-heavy cover layers don't rerender 60 times per second while rolling.
const MemoSleeveCover = React.memo(SleeveCover)

type RecordProps = {
    title: string
    size: number
    vinyl: Vinyl
    visible: boolean
}
function VinylDisc({ title, size, vinyl, visible }: RecordProps) {
    const labelDiameter = vinyl.labelScale * 100
    const duration = clamp(vinyl.animationSeconds, 0.2, 2.5)
    const conic = `conic-gradient(from 18deg,rgba(255,255,255,${vinyl.shine * 0.52}),transparent 10%,rgba(255,255,255,${vinyl.shine * 0.05}) 21%,transparent 32%,rgba(255,255,255,${vinyl.shine * 0.32}) 43%,transparent 50%,rgba(255,255,255,${vinyl.shine * 0.43}) 67%,transparent 77%,rgba(255,255,255,${vinyl.shine * 0.15}) 92%,transparent)`
    return (
        <div
            style={{
                position: "absolute",
                width: size,
                height: size,
                left: 0,
                top: 0,
                zIndex: 1,
                borderRadius: "50%",
                transform: `translateX(${visible ? vinyl.reveal * 100 : 0}%) rotate(${visible && vinyl.spinOnOpen ? "22deg" : "0deg"})`,
                transition: `transform ${duration}s cubic-bezier(.2,.8,.2,1)`,
                boxShadow: `0 18px 26px rgba(0,0,0,.35),0 6px 10px rgba(0,0,0,.20)`,
            }}
        >
            <div
                style={{
                    position: "absolute",
                    inset: 0,
                    borderRadius: "50%",
                    overflow: "hidden",
                    background: `radial-gradient(circle at 49% 48%,#181818 0%,${vinyl.recordColor} 38%,#080808 78%,#272727 97%,#090909 99%)`,
                    border: "1px solid rgba(255,255,255,.25)",
                }}
            >
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        borderRadius: "50%",
                        backgroundImage: `repeating-radial-gradient(circle at center,rgba(255,255,255,${vinyl.grooves * 0.08}) 0px,rgba(255,255,255,${vinyl.grooves * 0.08}) 1px,transparent 2px,rgba(0,0,0,${vinyl.grooves * 0.38}) 4px,transparent 6px)`,
                        maskImage:
                            "radial-gradient(circle, transparent 0%, transparent 19%, black 23%, black 94%, transparent 99%)",
                    }}
                />
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        borderRadius: "50%",
                        background: conic,
                        mixBlendMode: "screen",
                    }}
                />
                <div
                    style={{
                        position: "absolute",
                        width: `${labelDiameter}%`,
                        height: `${labelDiameter}%`,
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%,-50%)",
                        borderRadius: "50%",
                        background: vinyl.labelColor,
                        border: "1px solid rgba(0,0,0,.12)",
                        boxShadow:
                            "0 0 0 1px rgba(255,255,255,.12),inset 0 0 22px rgba(0,0,0,.13)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        padding: "10%",
                        boxSizing: "border-box",
                    }}
                >
                    <div
                        style={{
                            color: vinyl.labelTextColor,
                            textAlign: "center",
                            fontWeight: 700,
                            fontSize: clamp(size * 0.023, 8, 13),
                            lineHeight: 1.2,
                            letterSpacing: "-.025em",
                            fontFamily: "Inter,Arial,sans-serif",
                            maxWidth: "100%",
                            overflow: "hidden",
                            display: "-webkit-box",
                            WebkitLineClamp: 2,
                            WebkitBoxOrient: "vertical",
                            wordBreak: "break-word",
                        }}
                    >
                        {title}
                    </div>
                </div>
                <div
                    style={{
                        position: "absolute",
                        width: clamp(size * 0.012, 4, 8),
                        height: clamp(size * 0.012, 4, 8),
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%,-50%)",
                        borderRadius: "50%",
                        background: "#222",
                        boxShadow:
                            "inset 0 1px 1px rgba(0,0,0,.8),0 0 0 2px rgba(255,255,255,.28)",
                    }}
                />
            </div>
        </div>
    )
}

/**
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 * @framerIntrinsicWidth 1180
 * @framerIntrinsicHeight 780
 */
export default function VinylProjectRoll(props: Partial<Props>) {
    const projects = props.projects?.length ? props.projects : SAMPLE_PROJECTS
    const autoRotate = props.autoRotate ?? true
    const secondsPerItem = clamp(props.secondsPerItem ?? 8.0, 2.5, 40)
    const direction = props.direction ?? "forward"
    const layout: Layout = React.useMemo(
        () => ({ ...DEFAULT_LAYOUT, ...props.layout }),
        [props.layout]
    )
    const sleeve: Sleeve = React.useMemo(
        () => ({ ...DEFAULT_SLEEVE, ...props.sleeve }),
        [props.sleeve]
    )
    const vinyl: Vinyl = React.useMemo(
        () => ({ ...DEFAULT_VINYL, ...props.vinyl }),
        [props.vinyl]
    )
    const interaction: Interaction = React.useMemo(
        () => ({ ...DEFAULT_INTERACTION, ...props.interaction }),
        [props.interaction]
    )

    const isStatic = useIsStaticRenderer()
    const rootRef = React.useRef<HTMLDivElement>(null)
    const viewport = useSize(rootRef)
    const count = projects.length
    const [reducedMotion, setReducedMotion] = React.useState(false)
    const [visualPosition, setVisualPosition] = React.useState(0)
    const positionRef = React.useRef(0)
    const targetRef = React.useRef(0)
    const pauseUntil = React.useRef(0)
    const hoverRef = React.useRef(false)
    const [focusIndex, setFocusIndex] = React.useState<number | null>(null)
    const [focusEntered, setFocusEntered] = React.useState(false)
    const focusRef = React.useRef<number | null>(null)
    focusRef.current = focusIndex
    const closeTimer = React.useRef<number | null>(null)
    const downRef = React.useRef({
        active: false,
        y: 0,
        last: 0,
        moved: false,
        pointerId: -1,
    })

    React.useEffect(() => {
        if (typeof window === "undefined" || !window.matchMedia) return
        const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
        const update = () => setReducedMotion(mq.matches)
        update()
        mq.addEventListener?.("change", update)
        return () => mq.removeEventListener?.("change", update)
    }, [])

    React.useEffect(() => {
        if (isStatic || reducedMotion || count < 2) return
        let raf = 0
        let previous = performance.now()
        const tick = (now: number) => {
            const dt = Math.min((now - previous) / 1000, 0.06)
            previous = now
            const paused =
                focusRef.current !== null ||
                now < pauseUntil.current ||
                (interaction.pauseOnHover && hoverRef.current)
            if (autoRotate && !paused && !downRef.current.active) {
                // Constant gentle speed: 1 complete item per N seconds, no acceleration.
                targetRef.current +=
                    (dt / secondsPerItem) * (direction === "reverse" ? -1 : 1)
            }
            const factor = 1 - Math.exp(-11 * dt)
            const next =
                positionRef.current +
                (targetRef.current - positionRef.current) * factor
            if (Math.abs(next - positionRef.current) > 0.000005) {
                positionRef.current = next
                setVisualPosition(next)
            }
            // Keep floating-point values small on very long published sessions.
            if (Math.abs(positionRef.current) > count * 300) {
                const shift = Math.trunc(positionRef.current / count) * count
                positionRef.current -= shift
                targetRef.current -= shift
            }
            raf = requestAnimationFrame(tick)
        }
        raf = requestAnimationFrame(tick)
        return () => cancelAnimationFrame(raf)
    }, [
        autoRotate,
        secondsPerItem,
        direction,
        count,
        isStatic,
        reducedMotion,
        interaction.pauseOnHover,
    ])

    React.useEffect(() => {
        const el = rootRef.current
        if (!el || !interaction.wheelEnabled || isStatic) return
        const listener = (event: WheelEvent) => {
            if (focusRef.current !== null || count < 2) return
            event.preventDefault()
            let dy = event.deltaY
            if (event.deltaMode === 1) dy *= 16
            if (event.deltaMode === 2) dy *= Math.max(300, viewport.height)
            dy = clamp(dy, -260, 260)
            targetRef.current += dy / Math.max(75, interaction.wheelPixels)
            pauseUntil.current = performance.now() + 2100
        }
        el.addEventListener("wheel", listener, { passive: false })
        return () => el.removeEventListener("wheel", listener)
    }, [
        interaction.wheelEnabled,
        interaction.wheelPixels,
        isStatic,
        count,
        viewport.height,
    ])

    const openProject = React.useCallback(
        (index: number) => {
            if (focusRef.current !== null || downRef.current.moved) return
            targetRef.current = nearestPositionTo(
                index,
                targetRef.current,
                count
            )
            pauseUntil.current = performance.now() + 3000
            if (closeTimer.current !== null)
                window.clearTimeout(closeTimer.current)
            setFocusIndex(index)
            setFocusEntered(false)
            requestAnimationFrame(() =>
                requestAnimationFrame(() => setFocusEntered(true))
            )
        },
        [count]
    )

    const closeProject = React.useCallback(() => {
        setFocusEntered(false)
        if (closeTimer.current !== null) window.clearTimeout(closeTimer.current)
        closeTimer.current = window.setTimeout(
            () => {
                setFocusIndex(null)
                pauseUntil.current = performance.now() + 1600
            },
            Math.max(260, vinyl.animationSeconds * 1000 * 0.85)
        )
    }, [vinyl.animationSeconds])

    React.useEffect(() => {
        const handler = (event: KeyboardEvent) => {
            if (event.key === "Escape" && focusRef.current !== null)
                closeProject()
            if (
                !isStatic &&
                focusRef.current === null &&
                count > 1 &&
                (event.key === "ArrowDown" || event.key === "ArrowUp") &&
                rootRef.current?.contains(document.activeElement)
            ) {
                event.preventDefault()
                targetRef.current += event.key === "ArrowDown" ? 1 : -1
                pauseUntil.current = performance.now() + 2500
            }
        }
        window.addEventListener("keydown", handler)
        return () => window.removeEventListener("keydown", handler)
    }, [closeProject, isStatic, count])

    React.useEffect(
        () => () => {
            if (closeTimer.current !== null)
                window.clearTimeout(closeTimer.current)
        },
        []
    )

    function onPointerDown(event: React.PointerEvent<HTMLDivElement>) {
        if (isStatic || !interaction.dragEnabled || focusIndex !== null) return
        if (event.button !== 0) return
        downRef.current = {
            active: true,
            y: event.clientY,
            last: event.clientY,
            moved: false,
            pointerId: event.pointerId,
        }
    }
    function onPointerMove(event: React.PointerEvent<HTMLDivElement>) {
        const state = downRef.current
        if (!state.active || !interaction.dragEnabled || focusIndex !== null)
            return
        const delta = event.clientY - state.last
        state.last = event.clientY
        if (Math.abs(event.clientY - state.y) > 7) {
            if (!state.moved) {
                state.moved = true
                try {
                    event.currentTarget.setPointerCapture(state.pointerId)
                } catch {}
            }
            targetRef.current -= delta / Math.max(85, interaction.dragPixels)
            pauseUntil.current = performance.now() + 2400
        }
    }
    function onPointerEnd(event: React.PointerEvent<HTMLDivElement>) {
        if (
            downRef.current.active &&
            downRef.current.pointerId === event.pointerId
        ) {
            downRef.current.active = false
            try {
                if (event.currentTarget.hasPointerCapture(event.pointerId))
                    event.currentTarget.releasePointerCapture(event.pointerId)
            } catch {}
        }
    }

    const coverSize = Math.max(
        100,
        Math.min(
            layout.coverSize,
            viewport.width / 1.62,
            viewport.height * 0.78
        )
    )
    const sizeScale = coverSize / Math.max(180, layout.coverSize)
    // Actual center-to-center distance is editable independently of the depth falloff.
    // This keeps the sleeves legible as Spacing increases instead of pushing them far away in Z.
    const rowSpacing = layout.rowSpacing * sizeScale
    const cylinderRadius = rowSpacing / Math.sin(0.46)
    const depthRadius = Math.min(cylinderRadius, 430 * sizeScale)
    const maxSide = Math.min(
        layout.visibleNeighbors + 0.55,
        Math.max(1.35, count / 2)
    )
    const overlayProject = focusIndex !== null ? projects[focusIndex] : null
    const focusedSize = coverSize
    const dark = backgroundLuminance(layout.background) < 0.35

    return (
        <div
            ref={rootRef}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerEnd}
            onPointerCancel={onPointerEnd}
            onMouseEnter={() => {
                hoverRef.current = true
            }}
            onMouseLeave={() => {
                hoverRef.current = false
            }}
            role="region"
            aria-label="Interactive vinyl sleeve project gallery"
            style={{
                position: "relative",
                height: "100%",
                width: "100%",
                overflow: "hidden",
                background: layout.background,
                perspective: `${layout.perspective}px`,
                perspectiveOrigin: "50% 50%",
                cursor:
                    interaction.dragEnabled && !isStatic ? "grab" : "default",
                touchAction:
                    interaction.dragEnabled && !isStatic ? "none" : "auto",
                userSelect: "none",
                boxSizing: "border-box",
                isolation: "isolate",
            }}
        >
            {/* A restrained studio backdrop. There is deliberately no header or brand text. */}
            <div
                style={{
                    position: "absolute",
                    inset: 0,
                    pointerEvents: "none",
                    background:
                        "radial-gradient(ellipse at 50% 48%,rgba(255,255,255,.16),transparent 57%)",
                }}
            />
            {projects.map((project, i) => {
                const relative = wrappedDelta(i, visualPosition, count)
                const abs = Math.abs(relative)
                if (abs > maxSide) return null
                const angle = relative * 0.46
                const yy =
                    Math.sin(angle) * cylinderRadius + layout.verticalOffset
                const zz = (Math.cos(angle) - 1) * depthRadius * 1.12
                const tilt = clamp(layout.idleTilt + relative * 4, 40, 82)
                const scale = Math.max(0.7, 1 - abs * 0.045)
                const fadeStart = Math.max(0.9, maxSide - 0.6)
                const edgeFade = clamp(
                    (maxSide - abs) / (maxSide - fadeStart),
                    0,
                    1
                )
                const opacity = clamp(edgeFade * (1 - abs * 0.035), 0, 1)
                return (
                    <button
                        type="button"
                        key={i}
                        data-cover-index={i}
                        tabIndex={focusIndex !== null ? -1 : 0}
                        aria-label={`Open ${project.title || `project ${i + 1}`} record sleeve`}
                        onClick={() => openProject(i)}
                        onKeyDown={(e) => {
                            if (e.key === "Enter" || e.key === " ") {
                                e.preventDefault()
                                openProject(i)
                            }
                        }}
                        style={{
                            all: "unset",
                            position: "absolute",
                            left: "50%",
                            top: "50%",
                            width: coverSize,
                            height: coverSize,
                            transform: `translate3d(-50%,-50%,${zz}px) translateY(${yy}px) rotateX(${tilt}deg) scale(${scale})`,
                            transformOrigin: "50% 50%",
                            transformStyle: "preserve-3d",
                            backfaceVisibility: "hidden",
                            opacity:
                                focusIndex === i ? opacity * 0.13 : opacity,
                            zIndex: Math.round(300 - abs * 40),
                            pointerEvents:
                                opacity < 0.18 || focusIndex !== null
                                    ? "none"
                                    : "auto",
                            cursor: "pointer",
                            WebkitTapHighlightColor: "transparent",
                        }}
                    >
                        <MemoSleeveCover
                            project={project}
                            size={coverSize}
                            layout={layout}
                            sleeve={sleeve}
                        />
                    </button>
                )
            })}
            {overlayProject && (
                <div
                    role="dialog"
                    aria-modal="true"
                    aria-label={overlayProject.title || "Selected project"}
                    style={{
                        position: "absolute",
                        inset: 0,
                        zIndex: 1000,
                        display: "flex",
                        justifyContent: "center",
                        alignItems: "center",
                        flexDirection: "column",
                        opacity: focusEntered ? 1 : 0,
                        background: dark
                            ? "rgba(7,7,7,.74)"
                            : "rgba(244,241,234,.83)",
                        backdropFilter: `blur(${focusEntered ? 7 : 0}px)`,
                        transition: `opacity ${Math.min(vinyl.animationSeconds, 0.55)}s ease,backdrop-filter .5s ease`,
                    }}
                >
                    <button
                        type="button"
                        aria-label="Close record"
                        onClick={closeProject}
                        style={{
                            position: "absolute",
                            inset: 0,
                            cursor: "default",
                            border: "none",
                            background: "none",
                            zIndex: 0,
                        }}
                    />
                    {interaction.showCloseButton && (
                        <button
                            type="button"
                            aria-label="Close"
                            onClick={closeProject}
                            style={{
                                position: "absolute",
                                zIndex: 20,
                                right: 20,
                                top: 20,
                                width: 40,
                                height: 40,
                                borderRadius: "50%",
                                background: dark
                                    ? "rgba(255,255,255,.13)"
                                    : "rgba(255,255,255,.9)",
                                border: "1px solid rgba(100,100,100,.18)",
                                cursor: "pointer",
                                display: "grid",
                                placeItems: "center",
                                color: dark ? "white" : "#202020",
                                fontSize: 23,
                                boxShadow: "0 3px 12px rgba(0,0,0,.09)",
                            }}
                        >
                            ×
                        </button>
                    )}
                    <div
                        style={{
                            width: focusedSize,
                            height: focusedSize,
                            position: "relative",
                            flexShrink: 0,
                            zIndex: 2,
                            transform: `translateX(-${(focusedSize * vinyl.reveal) / 2}px) scale(${focusEntered ? 1 : 0.84}) rotateX(${focusEntered ? 0 : 15}deg)`,
                            transition: `transform ${vinyl.animationSeconds}s cubic-bezier(.18,.82,.24,1)`,
                            transformStyle: "preserve-3d",
                            pointerEvents: "auto",
                        }}
                    >
                        <VinylDisc
                            title={
                                overlayProject.discLabel ||
                                overlayProject.title ||
                                "Untitled"
                            }
                            size={focusedSize}
                            vinyl={vinyl}
                            visible={focusEntered}
                        />
                        <div
                            style={{
                                position: "absolute",
                                inset: 0,
                                zIndex: 3,
                            }}
                        >
                            <MemoSleeveCover
                                project={overlayProject}
                                size={focusedSize}
                                layout={layout}
                                sleeve={sleeve}
                            />
                        </div>
                    </div>
                    {interaction.showDescription &&
                        (overlayProject.description || overlayProject.link) && (
                            <div
                                style={{
                                    position: "relative",
                                    zIndex: 4,
                                    width: Math.min(
                                        viewport.width * 0.9,
                                        focusedSize * 1.6
                                    ),
                                    marginTop: 28,
                                    color: dark ? "#f5f5f5" : "#222",
                                    display: "flex",
                                    flexDirection: "column",
                                    alignItems: "center",
                                    gap: 10,
                                    textAlign: "center",
                                    fontFamily: "Inter,Arial,sans-serif",
                                    fontSize: 14,
                                }}
                            >
                                {overlayProject.description && (
                                    <span
                                        style={{
                                            maxWidth: 460,
                                            lineHeight: 1.5,
                                        }}
                                    >
                                        {overlayProject.description}
                                    </span>
                                )}
                                {overlayProject.link && (
                                    <a
                                        href={overlayProject.link}
                                        target={
                                            interaction.newTab
                                                ? "_blank"
                                                : "_self"
                                        }
                                        rel={
                                            interaction.newTab
                                                ? "noopener noreferrer"
                                                : undefined
                                        }
                                        style={{
                                            fontWeight: 700,
                                            color: "inherit",
                                            textDecoration: "underline",
                                            textUnderlineOffset: 4,
                                        }}
                                    >
                                        View project ↗
                                    </a>
                                )}
                            </div>
                        )}
                </div>
            )}
        </div>
    )
}

function backgroundLuminance(color: string) {
    if (!/^#[0-9a-f]{6}$/i.test(color)) return 1
    const r = parseInt(color.slice(1, 3), 16) / 255
    const g = parseInt(color.slice(3, 5), 16) / 255
    const b = parseInt(color.slice(5, 7), 16) / 255
    return 0.2126 * r + 0.7152 * g + 0.0722 * b
}

